'use strict';

const raven = require('raven');

const YandexLoggerSentryTransport = require('./transport');

// Все доступные уровни в Sentry: https://docs.sentry.io/clientdev/attributes/
const levelsMap = {
    FATAL: 'fatal',
    ERROR: 'error',
    WARN: 'warning',
    INFO: 'info',
    DEBUG: 'debug',
};

raven.disableConsoleAlerts();

class ErrorWrapper extends Error {
    constructor(err) {
        super();
        Object.assign(this, err);
    }
}

/**
 * Стрим для yandex-logger, позволяющий писать логи в Sentry.
 *
 * @param {YandexLoggerSentryStreamConfig} config
 * @returns {WritableStream}
 */
module.exports = config => {
    let options = Object.assign({
        transport: new YandexLoggerSentryTransport(config.transportOptions),
    }, config.clientOptions);

    let client = new raven.Client(config.dsn, options);

    return {
        /**
         * @param {Object} record
         * @returns {undefined}
         */
        write(record) {
            let level = levelsMap[record.levelName];
            if (level) {
                let err = record.err;
                let kwargs = parseRecord(record, level);

                if (err) {
                    if (!(err instanceof Error)) {
                        err = new ErrorWrapper(err);
                    }
                    client.captureException(err, kwargs);
                } else {
                    client.captureMessage(record.msg, kwargs);
                }
            }
        },
    };
};

/**
 * Сбор данных для отправки в Sentry
 * @param {Object} record
 * @param {String} level
 * @returns {Object}
 * @private
 */
function parseRecord(record, level) {
    let kwargs = Object.assign({
        level,
        logger: record.name,
        release: record.release,
        environment: record.environment,
        tags: record.tags,
        extra: record.data,
    }, record.sentry);

    if (record.req) {
        let req = record.req;
        let reqInfo = raven.parsers.parseRequest(req);

        // Если нет hostname, значит была использована мидлвара `middlewares/req.js`
        if (!req.hostname) {
            reqInfo.request.url = req.url;
        }

        Object.assign(kwargs, reqInfo);
    }

    if (record.user) {
        // See `middleware/blackbox.js` for record format
        kwargs.user = Object.assign({}, kwargs.user, record.user, {
            id: record.user.uid,
            username: record.user.login,
        });
        kwargs.user.uid = undefined;
        kwargs.user.login = undefined;
    }

    if (record.group) {
        // Display our group name instead of first stacktrace frame
        kwargs.culprit = record.group;

        // Override checksum to split events with identical stacktrace(message) but different groups
        kwargs.checksum = record.group;
    } else if (record.err) {
        // Display message instead of first stacktrace frame
        kwargs.culprit = record.msg;
    } else {
        // Override checksum to split events by message format
        kwargs.checksum = record.msgFormat;
    }

    return kwargs;
}

/**
 * @typedef {Object} YandexLoggerSentryStreamConfig
 * @property {String} dsn
 * @property {raven.ConstructorOptions} [clientOptions] - Настройки клиента Raven
 * @property {import("got").OptionsInit} [transportOptions] - Настройки для запроса через got.js
 */
